source('/home/jinshengxi/bladder_metabolism/cellchat_nichechat_fibro7/scripts/nichenet_common.R')
writeLines('PREFLIGHT',file.path(NN_OUT,'NICHENET_STATUS.txt'))
manifest<-jsonlite::fromJSON(file.path(NN_OUT,'resource_download_manifest.json'))
paths<-setNames(file.path(NN_OUT,NN_RESOURCES),names(NN_RESOURCES))
stopifnot(all(file.exists(paths)))
md5<-unname(tools::md5sum(paths));expected<-sub('^md5:','',manifest$official_checksum[match(NN_RESOURCES,manifest$resource)])
stopifnot(identical(md5,expected))
installed<-requireNamespace('nichenetr',quietly=TRUE)
pkg_version<-if(installed)as.character(packageVersion('nichenetr')) else 'NOT_INSTALLED'
lt<-readRDS(paths[['ligand_target']]);lr<-as.data.table(readRDS(paths[['ligand_receptor']]));weighted<-readRDS(paths[['weighted_networks']])
stopifnot(is.matrix(lt),is.numeric(lt),nrow(lt)>0,ncol(lt)>0,!anyDuplicated(rownames(lt)),!anyDuplicated(colnames(lt)),all(is.finite(lt)),all(lt>=0),all(c('from','to')%in%names(lr)),all(c('lr_sig','gr')%in%names(weighted)))
lr_unique<-unique(lr[,.(ligand=as.character(from),receptor=as.character(to))])
sample_manifest<-fread(file.path(ROOT,'01_metadata/per_sample_input_manifest.tsv'))
i<-which.min(sample_manifest$included_cells)
input<-qs2::qs_read(sample_manifest$input_path[i],nthreads=1)
genes<-rownames(input$expression)
symbols<-list(ligand_target_targets=rownames(lt),ligand_target_ligands=colnames(lt),LR_ligands=unique(lr_unique$ligand),LR_receptors=unique(lr_unique$receptor),weighted_lr_sig_nodes=unique(c(weighted$lr_sig$from,weighted$lr_sig$to)),weighted_gr_nodes=unique(c(weighted$gr$from,weighted$gr$to)))
compat<-rbindlist(lapply(names(symbols),function(n){g<-symbols[[n]];data.table(resource_component=n,n_resource_symbols=length(g),n_exact_RNA_matches=sum(g%in%genes),n_unmatched=sum(!g%in%genes),resource_match_fraction=mean(g%in%genes),n_RNA_genes=length(genes),RNA_match_fraction=sum(genes%in%g)/length(genes),matching_rule='exact case-sensitive; no remapping')}))
write_tsv(compat,'05_nichenet_preflight/gene_symbol_compatibility_summary.tsv')
symbols_long<-rbindlist(lapply(names(symbols),function(n)data.table(resource_component=n,gene=symbols[[n]],in_RNA=symbols[[n]]%in%genes)))
write_tsv(symbols_long,'05_nichenet_preflight/resource_gene_symbol_matching.tsv')
write_tsv(lr_unique,'05_nichenet_preflight/official_human_LR_network.tsv')
writeLines(genes,file.path(NN_OUT,'RNA_gene_symbols.txt'))
resource_summary<-data.table(resource=NN_RESOURCES,path=paths,bytes=file.info(paths)$size,official_md5=expected,actual_md5=md5,sha256=vapply(paths,sha256,character(1)),verified=md5==expected)
write_tsv(resource_summary,'05_nichenet_preflight/verified_resource_manifest.tsv')
capture.output(list(ligand_target=list(dim=dim(lt),class=class(lt),range=range(lt),target_example=head(rownames(lt)),ligand_example=head(colnames(lt))),ligand_receptor=list(dim=dim(lr),columns=names(lr),unique_links=nrow(lr_unique),head=head(lr)),weighted_networks=lapply(weighted,function(x)list(dim=dim(x),columns=names(x),head=head(x)))),file=file.path(NN_OUT,'actual_resource_structure.txt'))
if(installed)capture.output(lapply(c('predict_ligand_activities','get_weighted_ligand_target_links','get_expressed_genes'),function(n)list(function_name=n,formals=formals(get(n,asNamespace('nichenetr'))))),file=file.path(NN_OUT,'actual_nichenetr_API.txt'))
settings<-list(sender_groups=GROUPS[1:7],receiver_groups=GROUPS[8:14],ligands=sort(unique(lr_unique$ligand)),receptors=sort(unique(lr_unique$receptor)),target_genes=rownames(lt),modeled_ligands=colnames(lt),resource_paths=paths,lr_network=lr_unique,seed=123,group_min_cells=30,diagnostic_expression_fraction=.10,geneset_oi=NULL)
saveRDS(settings,file.path(NN_OUT,'frozen_nichenet_preflight_inputs.rds'))
commit<-jsonlite::fromJSON(file.path(NN_OUT,'official_nichenetr_commit.json'))$sha
write_tsv(data.table(metric=c('installed','package_version','official_repository','source_commit','input_expression','sender','candidate_receiver','resource_record','ligand_target_dimensions','LR_unique_pairs','weighted_network_components','matching_rule','spatial_information_required','per_sample_support','geneset_oi','ligand_activity_run','expression_audit_cutoff','sample_group_min_cells','seed'),value=c(installed,pkg_version,'https://github.com/saeyslab/nichenetr',commit,'Frozen RNA/data LogNormalize; expression matrices per biological sample',paste(GROUPS[1:7],collapse=';'),paste(GROUPS[8:14],collapse=';'),'https://zenodo.org/records/7074291',paste(dim(lt),collapse='x'),nrow(lr_unique),paste(names(weighted),collapse=';'),'Exact case-sensitive; source expression untouched','NO','API can run on per-sample eligible ligand/background lists; no built-in cohort biological-replication model','UNDEFINED','FALSE','RNA/data>0 detection; pct>=0.10 is a diagnostic flag, not geneset_oi or inferred mechanism',30,123)),'05_nichenet_preflight/nichenet_preflight_metrics.tsv')
writeLines(c('# Official NicheNet pre-flight audit','',paste0('- Installed nichenetr: ',installed,'; version: ',pkg_version,'; fixed commit: ',commit,'.'),'- Source: [official saeyslab/nichenetr](https://github.com/saeyslab/nichenetr). Human v2 model: [Zenodo 7074291](https://zenodo.org/records/7074291), as linked by the official ligand-activity vignette.','- All three resources are locally available, loaded and checksum verified: ligand-target matrix, human ligand-receptor network, weighted networks. Exact paths, official MD5, local SHA256 and byte sizes are in verified_resource_manifest.tsv.','- Existing local proxy failed CERN TLS; direct verified TLS to Zenodo succeeded. No model replacement or disabled certificate verification was used.',paste0('- Ligand-target matrix: ',nrow(lt),' target genes x ',ncol(lt),' ligands. LR unique pairs: ',nrow(lr_unique),'. Weighted components: ',paste(names(weighted),collapse=', '),'.'),'- RNA symbols are read directly from a frozen sample RNA/data matrix, with the same full gene universe as the authoritative atlas. Matching is exact and case-sensitive; unmatched symbols remain explicit. Expression identifiers and values are not renamed/recomputed.','',paste(capture.output(print(compat)),collapse='\n'),'','## Scope and receiver-program gate','', '- Sender: frozen Fibro_C0–C6. Candidate receivers: Epithelial, Myeloid, Endothelial, T_NK; B, Plasma, Mast remain available when supported by CellChat. No pooled network or generic 14x14 NicheNet network.','- NicheNet links a potential ligand to a receiver target program through a prior model; ligand-target regulatory potential is distinct from inferred ligand activity. Expression gates alone do not establish receiver activity or causality.','- Per-sample sender ligand / receiver receptor expression is audited at group >=30 cells. Detection means RNA/data>0; a 10% expressed flag is included as an explicit diagnostic convention from the official workflow, alongside continuous fractions and means. It does not define geneset_oi.','- geneset_oi is UNDEFINED. No arbitrary marker list, top-DEG list, stage comparison, or CellChat pathway genes are silently used as the receiver program. Ligand-activity inference is not executed this round.','- NicheNet functions accept per-sample expressed background/potential ligands, but ordinary nichenetr does not itself implement a sample-replicated cohort test. The template records sample identity and leaves receiver program/sample evidence design explicit.','- Prioritization after CellChat will require: pair support; sender ligand expression; receiver receptor expression; receiver-program provenance; activity metrics; interpretable ligand-target links. CellChat receptor complexes remain recorded with subunits and are not naively equated to a single NicheNet receptor symbol.','- READY means environment/resources/expression audits/template are prepared; it does not mean ligand activity has run. PASS is reserved for a later completed NicheNet analysis with a frozen receiver program.'),file.path(NN_OUT,'NicheNet_preflight_audit.md'))
cat('NICHENET RESOURCE AUDIT COMPLETE; installed=',installed,'\n',sep='')
if(installed && all(file.exists(file.path(ROOT,c('06_nichenet_expression_audit/sender_ligand_expression_summary.tsv','06_nichenet_expression_audit/receiver_receptor_expression_summary.tsv','07_nichenet_templates/receiver_program_design_template.tsv')))))writeLines('READY',file.path(NN_OUT,'NICHENET_STATUS.txt'))
